//! Renders the TypeScript bindings for every Rust type that crosses into the UI.
#![forbid(unsafe_code)]

use specta::Types;
use specta_typescript::Typescript;

/// Path of the generated file, relative to the repository root.
pub const OUTPUT: &str = "packages/wf-wasm/src/bindings.ts";

/// First line of the generated file.
pub const HEADER: &str =
    "// Generated by crates/wf-bindings from the Rust types. Do not edit; run `npm run bindings`.";

/// Failure while rendering or writing the bindings.
#[derive(Debug, thiserror::Error)]
pub enum BindingsError {
    /// specta could not express a type in TypeScript.
    #[error("export failed: {0}")]
    Export(#[from] specta_typescript::Error),
    /// Reading or writing the output file failed.
    #[error("io on {path}: {source}")]
    Io {
        /// File that failed.
        path: std::path::PathBuf,
        /// Underlying error.
        source: std::io::Error,
    },
}

/// Every type exported to TypeScript. Add new types here.
#[must_use]
pub fn types() -> Types {
    Types::default().register::<wf_core::CoreInfo>()
}

/// Render the full bindings file.
///
/// # Errors
/// [`BindingsError::Export`] when a type cannot be expressed in TypeScript.
pub fn render() -> Result<String, BindingsError> {
    Ok(Typescript::default()
        .header(HEADER)
        .export(&types(), specta_serde::Format)?)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn render_starts_with_header() {
        let out = render().unwrap();
        assert!(out.starts_with(HEADER));
    }

    #[test]
    fn render_exports_core_info() {
        let out = render().unwrap();
        assert!(out.contains("export type CoreInfo"));
        assert!(out.contains("version: string"));
    }

    #[test]
    fn render_is_deterministic() {
        assert_eq!(render().unwrap(), render().unwrap());
    }
}
